import { createHash } from 'node:crypto';
import * as fs from 'node:fs';
import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { EXCLUDED_DIR_NAMES, EXCLUDED_FILE_NAMES, MAX_FILE_BYTES, MAX_FILES, MAX_TOTAL_BYTES, SCHEMA_VERSION, SECRET_DIR_NAMES, SECRET_FILE_SUFFIXES, SUPPORTED_MODES, } from './constants.js';
import { inspectSelectedUnit } from './discovery.js';
import { atomicWriteJson, draftDirectory, makeDraftId, normalizedRelative, nowIso, PublisherError, saveState, secureDirectory, setTreeReadOnly, setTreeWritable, sha256File, } from './util.js';
const ENV_FILE_PATTERN = /^\.env(?:[._-].*)?$/i;
const ENV_TEMPLATE_PATTERN = /^\.env(?:[._-](?:example|sample|template))$/i;
const PUBLISHER_BUILD_ONLY_DIRECTORIES = new Set([
    'packages/repo-to-stax-converter/template',
]);
export async function initializeDraft(options) {
    if (!SUPPORTED_MODES.includes(options.mode)) {
        throw new PublisherError(`Unsupported publish mode: ${options.mode}`, 'invalid_publish_mode');
    }
    const normalizedItemId = String(options.itemId ?? '').trim();
    if (options.mode === 'update' && !normalizedItemId) {
        throw new PublisherError('Update mode requires an explicit platform itemId. A name match is never enough.', 'missing_item_id');
    }
    if (options.mode === 'create' && normalizedItemId) {
        throw new PublisherError('Create mode must not include an itemId.', 'unexpected_item_id');
    }
    const workspace = await fsp.realpath(path.resolve(options.workspace)).catch(() => path.resolve(options.workspace));
    const selected = await inspectSelectedUnit(options.source, options.unitType, workspace);
    const draftId = options.draftId || makeDraftId();
    const directory = draftDirectory(draftId, options.env);
    if (fs.existsSync(directory)) {
        throw new PublisherError('Local draft already exists; choose a new draft ID.', 'draft_exists');
    }
    await secureDirectory(directory);
    const now = nowIso();
    const state = {
        schema_version: SCHEMA_VERSION,
        draft_id: draftId,
        status: 'selected',
        mode: options.mode,
        item_id: normalizedItemId || null,
        workspace_path: workspace,
        source_path: String(selected.path),
        unit: selected,
        created_at: now,
        updated_at: now,
        remote_draft_id: null,
        remote_artifact_id: null,
    };
    await saveState(directory, state);
    return { directory, state };
}
export async function stageSelected(directory, state) {
    const staging = path.join(directory, 'staging');
    if (fs.existsSync(staging)) {
        throw new PublisherError('This draft already has an immutable staging snapshot. Start a new local draft to restage source changes.', 'staging_exists');
    }
    const source = path.resolve(state.source_path);
    if (!fs.existsSync(source))
        throw new PublisherError('Selected source no longer exists.', 'missing_source');
    const temporary = path.join(directory, `.staging-${process.pid}`);
    if (fs.existsSync(temporary)) {
        await setTreeWritable(temporary);
        await fsp.rm(temporary, { recursive: true, force: true });
    }
    await secureDirectory(temporary);
    const exclusions = [];
    const copied = await copySource(source, temporary, exclusions);
    if (copied.fileCount === 0) {
        await setTreeWritable(temporary);
        await fsp.rm(temporary, { recursive: true, force: true });
        throw new PublisherError('No publishable files remain after staging exclusions.', 'empty_staging');
    }
    const manifest = await snapshotManifest(temporary);
    await fsp.rename(temporary, staging);
    await setTreeReadOnly(staging);
    await atomicWriteJson(path.join(directory, 'file-list.json'), manifest);
    await atomicWriteJson(path.join(directory, 'exclusions.json'), {
        schema_version: SCHEMA_VERSION,
        excluded: exclusions,
        count: exclusions.length,
    });
    state.status = 'staged';
    state.stage_sha256 = manifest.stage_sha256;
    state.file_count = manifest.file_count;
    state.total_bytes = manifest.total_bytes;
    state.updated_at = nowIso();
    await saveState(directory, state);
    return {
        stage_sha256: manifest.stage_sha256,
        file_count: manifest.file_count,
        total_bytes: manifest.total_bytes,
        excluded: exclusions,
    };
}
export async function assertStageUnchanged(directory, state) {
    const staging = path.join(directory, 'staging');
    if (!(await isDirectory(staging)))
        throw new PublisherError('Staging snapshot is missing.', 'missing_staging');
    const current = await snapshotManifest(staging);
    const expected = state.stage_sha256;
    if (!expected || current.stage_sha256 !== expected) {
        throw new PublisherError('The immutable staging snapshot changed after confirmation. Start a new local draft.', 'staging_changed', { expected: expected, actual: current.stage_sha256 });
    }
    return current;
}
export async function snapshotManifest(root) {
    const entries = [];
    let totalBytes = 0;
    await collectFiles(root, root, entries);
    entries.sort((left, right) => compareText(left.path, right.path));
    for (const entry of entries)
        totalBytes += entry.size;
    const canonical = entries
        .map((entry) => `${entry.path}\0${entry.size}\0${entry.sha256}\n`)
        .join('');
    return {
        schema_version: SCHEMA_VERSION,
        files: entries,
        file_count: entries.length,
        total_bytes: totalBytes,
        stage_sha256: createHash('sha256').update(canonical).digest('hex'),
    };
}
async function collectFiles(root, current, output) {
    const entries = await fsp.readdir(current, { withFileTypes: true });
    entries.sort((left, right) => compareText(left.name, right.name));
    for (const entry of entries) {
        const entryPath = path.join(current, entry.name);
        if (entry.isSymbolicLink() || (!entry.isFile() && !entry.isDirectory())) {
            throw new PublisherError('Staging contains a symlink or non-regular file.', 'unsafe_staging');
        }
        if (entry.isDirectory()) {
            await collectFiles(root, entryPath, output);
            continue;
        }
        const stat = await fsp.stat(entryPath);
        output.push({
            path: normalizedRelative(entryPath, root),
            size: stat.size,
            sha256: await sha256File(entryPath),
        });
    }
}
async function copySource(source, target, exclusions) {
    const counters = { fileCount: 0, totalBytes: 0 };
    const sourceStat = await fsp.stat(source);
    if (sourceStat.isFile()) {
        await copyFile(source, path.join(target, path.basename(source)), path.dirname(source), counters, exclusions);
        return counters;
    }
    if (!sourceStat.isDirectory())
        throw new PublisherError('Selected source must be a file or directory.', 'invalid_source');
    const visit = async (current) => {
        const entries = await fsp.readdir(current, { withFileTypes: true });
        entries.sort((left, right) => left.name.toLowerCase().localeCompare(right.name.toLowerCase()));
        for (const entry of entries) {
            const entryPath = path.join(current, entry.name);
            const relative = normalizedRelative(entryPath, source);
            if (entry.isSymbolicLink()) {
                exclusions.push({ path: relative, reason: 'symlink' });
            }
            else if (entry.isDirectory()) {
                const reason = PUBLISHER_BUILD_ONLY_DIRECTORIES.has(relative)
                    ? 'publisher_build_only_directory'
                    : excludedDirectoryReason(entry.name);
                if (reason)
                    exclusions.push({ path: relative, reason });
                else
                    await visit(entryPath);
            }
            else if (!entry.isFile()) {
                exclusions.push({ path: relative, reason: 'non_regular_file' });
            }
            else {
                await copyFile(entryPath, path.join(target, relative), source, counters, exclusions);
            }
        }
    };
    await visit(source);
    return counters;
}
async function copyFile(source, destination, root, counters, exclusions) {
    const relative = normalizedRelative(source, root);
    const reason = relative === '.taku/skill-conversion.json'
        ? 'local_skill_conversion_record'
        : excludedFileReason(path.basename(source));
    if (reason) {
        exclusions.push({ path: relative, reason });
        return;
    }
    const stat = await fsp.lstat(source);
    if (!stat.isFile()) {
        exclusions.push({ path: relative, reason: 'non_regular_file' });
        return;
    }
    if (stat.size > MAX_FILE_BYTES) {
        throw new PublisherError(`File exceeds the ${MAX_FILE_BYTES}-byte limit: ${relative}`, 'file_too_large');
    }
    if (counters.fileCount + 1 > MAX_FILES) {
        throw new PublisherError(`Package exceeds the ${MAX_FILES}-file limit.`, 'too_many_files');
    }
    if (counters.totalBytes + stat.size > MAX_TOTAL_BYTES) {
        throw new PublisherError(`Package exceeds the ${MAX_TOTAL_BYTES}-byte limit.`, 'package_too_large');
    }
    await secureDirectory(path.dirname(destination));
    await fsp.copyFile(source, destination, fs.constants.COPYFILE_EXCL);
    await fsp.chmod(destination, 0o600).catch(() => undefined);
    counters.fileCount += 1;
    counters.totalBytes += stat.size;
}
function excludedDirectoryReason(name) {
    const lower = name.toLowerCase();
    if (SECRET_DIR_NAMES.has(lower))
        return 'secret_directory';
    if (EXCLUDED_DIR_NAMES.has(lower))
        return 'cache_or_build_directory';
    return undefined;
}
function excludedFileReason(name) {
    const lower = name.toLowerCase();
    if (lower.startsWith('creator-profile-draft.') || lower === 'creator-profile-summary.md') {
        return 'local_creator_profile_draft';
    }
    if (EXCLUDED_FILE_NAMES.has(lower))
        return 'secret_or_machine_file';
    if (ENV_FILE_PATTERN.test(name) && !ENV_TEMPLATE_PATTERN.test(name))
        return 'environment_file';
    if (SECRET_FILE_SUFFIXES.has(path.extname(lower)))
        return 'secret_file_extension';
    return undefined;
}
async function isDirectory(candidate) {
    return fsp.stat(candidate).then((stat) => stat.isDirectory(), () => false);
}
function compareText(left, right) {
    return left < right ? -1 : left > right ? 1 : 0;
}
